"""
Generated grid: live w250 unlink. Cross-verified cell by cell at emit time.

Failure-Class: FC-privacy-purge-chain-collides-inside-armed-storm-window

Each test re-drives its cell through the real boundary
(``drive_cell``) and compares the full observable freeze against the
literal the emit-time cross-verify produced; the independent model walk and
the emitter live outside the tree. Do not edit frozen literals by hand.
"""

from tests.unit.batch_purge_storm_gate_grid_harness import drive_cell


def _drive(monkeypatch, caplog, **params):
    return drive_cell(monkeypatch, caplog, **params)


def test_g_abaa_enaa_rsac_wvaa_loaa_hoaa_geaa(monkeypatch, caplog) -> None:
    assert _drive(
        monkeypatch,
        caplog,
        label='batch_purge_job_unlink',
        aborts=0,
        entry_wait=0.0,
        residual_schedule=(0.0,),
        wave_wait=0.0,
        generation=0,
        hostile_peek=False,
        damper_mode='live',
        log_mode='info',
        arm_window=2.5,
    ) == {
        'result': 'erased',
        'raised': None,
        'retry_after': 0.0,
        'body_calls': [1],
        'sleeps': [],
        'damper_slept': [],
        'events': [['consult', 'batch_purge_job_unlink', 0.0]],
        'note_success': [['batch_purge_job_unlink', 0]],
        'consult_count': 1,
        'peek_count': 0,
        'records': [],
    }


